class UnionFind {
    std::vector<int> parent, size;
    int components;
public:
    explicit UnionFind(int n) : components(n) {
        if (n < 0) throw std::invalid_argument("negative size");
        parent.resize(n); size.assign(n, 1);
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (x < 0 || x >= (int)parent.size()) throw std::out_of_range("index");
        while (x != parent[x]) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) { int t = a; a = b; b = t; }
        parent[b] = a; size[a] += size[b]; --components; return true;
    }
    bool connected(int a, int b) { return find(a) == find(b); }
    int count() const { return components; }
};

