class FenwickTree {
    std::vector<long long> tree;
public:
    explicit FenwickTree(int n) {
        if (n < 0) throw std::invalid_argument("negative size");
        tree.assign((size_t)n + 1, 0);
    }
    void add(int index, long long delta) {
        if (index < 0 || (size_t)index >= tree.size() - 1) throw std::out_of_range("index");
        for (size_t i = (size_t)index + 1; i < tree.size(); i += i & -i) tree[i] += delta;
    }
    long long prefixSum(int end) const {
        if (end < 0 || (size_t)end >= tree.size()) throw std::out_of_range("end");
        long long sum = 0;
        for (size_t i = (size_t)end; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }
    long long rangeSum(int left, int right) const {
        if (left > right) throw std::invalid_argument("invalid range");
        return prefixSum(right) - prefixSum(left);
    }
};
